  if (last && last.v === String(payload) && now - last.t < 3000) return null;
  flow.set(key, {v: String(payload), t: now});
  return {topic: base + '/' + suffix, payload: payload};
}
if (isEcho('target')) return null;
const t = Number(msg.payload);
if (isNaN(t)) return null;
const want = Math.min(31, Math.max(16, t));
const rep = flow.get('fjx7_state_target');
if (rep !== undefined && Math.abs(rep - want) < 0.01) return null;
return toBridge('climate/ac/target_temperature/command', String(want));

